    ["Upgrades over what you're wearing, scored with your class's stat weights. Only gear you can use at your level, at most a quarter of your gold. Random-suffix items are scored by their base stats. Buy works at the auction house, one key press per purchase."] = "Verbesserungen gegenüber deiner Ausrüstung, bewertet mit den Wertegewichten deiner Klasse. Nur Ausrüstung, die du auf deiner Stufe tragen kannst, höchstens ein Viertel deines Golds. Gegenstände mit Zufallswerten werden nach ihren Grundwerten bewertet. Kaufen geht im Auktionshaus, ein Tastendruck pro Kauf.",
    ["Scroll with the mouse wheel. Skipped items are never bought on this character, on this list or later ones, until you untick them. Green 'Now' = cheaper than your max in the last scan."] = "Mit dem Mausrad scrollen. Übersprungene Gegenstände kauft dieser Charakter nie, auf dieser Liste und späteren, bis du sie wieder abhakst. Grünes 'Jetzt' = günstiger als dein Maximum im letzten Scan.",
    ["Press the key you want for\n|cffffd200"] = "Drücke die gewünschte Taste für\n|cffffd200",
    ["Auto-target: nearest enemy when you have none. Tank: click an ally, then the key hits what's on them."] = "Auto-Ziel: nächster Gegner, wenn du keinen hast. Tank: klicke einen Verbündeten an, dann trifft die Taste, was ihn angreift.",
    ["Buy / post / scan buttons appear next to the auction house when you open it."] = "Kauf-, Einstell- und Scanknöpfe erscheinen neben dem Auktionshaus, wenn du es öffnest.",
    ["Key: "] = "Taste: ",
    ["Big-button key: "] = "Taste für den großen Knopf: ",
    ["Source: "] = "Quelle: ",
    ["No guide data for this class"] = "Keine Guide-Daten für diese Klasse",
    ["|cff33ff99Flip|rForever Advisor"] = "|cff33ff99Flip|rForever Berater",
    ["|cff33ff99Flip|rForever Profession planner"] = "|cff33ff99Flip|rForever Berufsplaner",
    ["Open a profession window once - FlipForever reads its recipes."] = "Öffne einmal ein Berufsfenster - FlipForever liest die Rezepte.",
    ["Profit after the 5% AH cut and deposit. Only results that sell at least 3 a day; amounts sized to sell within about two days."] = "Gewinn nach 5 % AH-Gebühr und Anzahlung. Nur Ergebnisse, die sich mindestens 3-mal am Tag verkaufen; Mengen so, dass sie in etwa zwei Tagen verkauft sind.",
    ["Chance to skill up: orange 100%; yellow and green exact once a recipe has changed colour in front of FlipForever (else ~75% / ~25%). Prices: your scans, vendor goods ~4x sell price."] = "Chance auf Skillpunkt: orange 100 %; gelb und grün genau, sobald ein Rezept vor FlipForever die Farbe gewechselt hat (sonst ~75 % / ~25 %). Preise: deine Scans, Händlerware ~4x Verkaufspreis.",
    ["Your auctions: none up"] = "Deine Auktionen: keine aktiv",
