    ["Find upgrades for your character in your latest scan."] = "Trouvez des améliorations pour votre personnage dans votre dernier scan.",
    ["Upgrades over what you're wearing, scored with your class's stat weights. Only gear you can use at your level, at most a quarter of your gold. Random-suffix items are scored by their base stats. Buy works at the auction house, one key press per purchase."] = "Améliorations par rapport à votre équipement, notées avec les pondérations de votre classe. Seulement l'équipement utilisable à votre niveau, au plus un quart de votre or. Les objets à suffixe aléatoire sont notés sur leurs caractéristiques de base. L'achat se fait à l'hôtel des ventes, une touche par achat.",
    ["Scroll with the mouse wheel. Skipped items are never bought on this character, on this list or later ones, until you untick them. Green 'Now' = cheaper than your max in the last scan."] = "Faites défiler avec la molette. Les objets ignorés ne sont jamais achetés par ce personnage, sur cette liste ou les suivantes, tant qu'ils restent cochés. 'Actuel' en vert = moins cher que votre maximum au dernier scan.",
    ["Press the key you want for\n|cffffd200"] = "Appuyez sur la touche voulue pour\n|cffffd200",
    ["Auto-target: nearest enemy when you have none. Tank: click an ally, then the key hits what's on them."] = "Ciblage auto : l'ennemi le plus proche si vous n'en avez pas. Tank : cliquez sur un allié, la touche frappe ce qui l'attaque.",
    ["Buy / post / scan buttons appear next to the auction house when you open it."] = "Les boutons d'achat, de mise en vente et de scan apparaissent à côté de l'hôtel des ventes quand vous l'ouvrez.",
