    ["Find upgrades for your character in your latest scan."] = "Busca mejoras para tu personaje en tu último escaneo.",
    ["Upgrades over what you're wearing, scored with your class's stat weights. Only gear you can use at your level, at most a quarter of your gold. Random-suffix items are scored by their base stats. Buy works at the auction house, one key press per purchase."] = "Mejoras sobre tu equipo, puntuadas con los pesos de estadísticas de tu clase. Solo equipo que puedes usar a tu nivel, como mucho una cuarta parte de tu oro. Los objetos con sufijo aleatorio se puntúan por sus estadísticas base. Se compra en la casa de subastas, una tecla por compra.",
    ["Scroll with the mouse wheel. Skipped items are never bought on this character, on this list or later ones, until you untick them. Green 'Now' = cheaper than your max in the last scan."] = "Desplázate con la rueda del ratón. Los objetos omitidos nunca se compran con este personaje, en esta lista ni en las siguientes, hasta que los desmarques. 'Ahora' en verde = más barato que tu máximo en el último escaneo.",
    ["Press the key you want for\n|cffffd200"] = "Pulsa la tecla que quieras para\n|cffffd200",
    ["Auto-target: nearest enemy when you have none. Tank: click an ally, then the key hits what's on them."] = "Objetivo auto: el enemigo más cercano si no tienes ninguno. Tanque: haz clic en un aliado y la tecla golpea lo que lo ataca.",
    ["Buy / post / scan buttons appear next to the auction house when you open it."] = "Los botones de comprar, publicar y escanear aparecen junto a la casa de subastas al abrirla.",
