    ["Chance to skill up: orange 100%; yellow and green exact once a recipe has changed colour in front of FlipForever (else ~75% / ~25%). Prices: your scans, vendor goods ~4x sell price."] = "Probabilidad de subir: naranja 100 %; amarillo y verde exactos cuando una receta cambia de color ante FlipForever (si no, ~75 % / ~25 %). Precios: tus escaneos, productos de comerciante ~4x su precio de venta.",
