    ["Upgrades over what you're wearing, scored with your class's stat weights. Only gear you can use at your level, at most a quarter of your gold. Random-suffix items are scored by their base stats. Buy works at the auction house, one key press per purchase."] = "Miglioramenti rispetto a ciò che indossi, valutati con i pesi delle statistiche della tua classe. Solo equipaggiamento usabile al tuo livello, al massimo un quarto del tuo oro. Gli oggetti con suffisso casuale sono valutati sulle statistiche base. L'acquisto avviene alla casa d'aste, un tasto per acquisto.",
    ["Scroll with the mouse wheel. Skipped items are never bought on this character, on this list or later ones, until you untick them. Green 'Now' = cheaper than your max in the last scan."] = "Scorri con la rotellina. Gli oggetti saltati non vengono mai comprati da questo personaggio, in questa lista o nelle successive, finché non li deselezioni. 'Ora' in verde = più economico del tuo massimo nell'ultima scansione.",
