    ["Chance to skill up: orange 100%; yellow and green exact once a recipe has changed colour in front of FlipForever (else ~75% / ~25%). Prices: your scans, vendor goods ~4x sell price."] = "Probabilità di salire: arancione 100%; giallo e verde esatti quando una ricetta ha cambiato colore davanti a FlipForever (altrimenti ~75% / ~25%). Prezzi: le tue scansioni, merci da mercante ~4x il prezzo di vendita.",
