    ["Find upgrades for your character in your latest scan."] = "Encontre melhorias para o seu personagem no último escaneamento.",
    ["Upgrades over what you're wearing, scored with your class's stat weights. Only gear you can use at your level, at most a quarter of your gold. Random-suffix items are scored by their base stats. Buy works at the auction house, one key press per purchase."] = "Melhorias sobre o que você usa, pontuadas com os pesos de atributos da sua classe. Só equipamento que você usa no seu nível, no máximo um quarto do seu ouro. Itens com sufixo aleatório são pontuados pelos atributos base. A compra é feita na Casa de Leilões, uma tecla por compra.",
    ["Scroll with the mouse wheel. Skipped items are never bought on this character, on this list or later ones, until you untick them. Green 'Now' = cheaper than your max in the last scan."] = "Role com a roda do mouse. Itens pulados nunca são comprados por este personagem, nesta lista ou nas próximas, até você desmarcá-los. 'Agora' em verde = mais barato que o seu máximo no último escaneamento.",
    ["Press the key you want for\n|cffffd200"] = "Pressione a tecla que deseja para\n|cffffd200",
    ["Auto-target: nearest enemy when you have none. Tank: click an ally, then the key hits what's on them."] = "Alvo automático: o inimigo mais próximo se você não tiver um. Tanque: clique num aliado e a tecla acerta quem o ataca.",
    ["Buy / post / scan buttons appear next to the auction house when you open it."] = "Os botões de comprar, anunciar e escanear aparecem ao lado da Casa de Leilões quando você a abre.",
    ["Key: "] = "Tecla: ",
    ["Big-button key: "] = "Tecla do botão grande: ",
    ["Source: "] = "Fonte: ",
    ["No guide data for this class"] = "Sem dados de guia para esta classe",
