    ["|cff33ff99Flip|rForever Profession planner"] = "|cff33ff99Flip|rForever Planejador de profissões",
    ["Open a profession window once - FlipForever reads its recipes."] = "Abra uma vez a janela de uma profissão - o FlipForever lê as receitas.",
    ["Profit after the 5% AH cut and deposit. Only results that sell at least 3 a day; amounts sized to sell within about two days."] = "Lucro após a taxa de 5% e o depósito. Só resultados que vendem pelo menos 3 por dia; quantidades para vender em cerca de dois dias.",
    ["Chance to skill up: orange 100%; yellow and green exact once a recipe has changed colour in front of FlipForever (else ~75% / ~25%). Prices: your scans, vendor goods ~4x sell price."] = "Chance de subir: laranja 100%; amarelo e verde exatos quando uma receita mudou de cor diante do FlipForever (senão ~75% / ~25%). Preços: seus escaneamentos, itens de comerciante ~4x o preço de venda.",
