    ["Upgrades over what you're wearing, scored with your class's stat weights. Only gear you can use at your level, at most a quarter of your gold. Random-suffix items are scored by their base stats. Buy works at the auction house, one key press per purchase."] = "Улучшения по сравнению с надетым, по весам характеристик вашего класса. Только снаряжение, доступное на вашем уровне, не дороже четверти вашего золота. Предметы со случайными свойствами оцениваются по базовым характеристикам. Покупка на аукционе, одно нажатие на покупку.",
    ["Scroll with the mouse wheel. Skipped items are never bought on this character, on this list or later ones, until you untick them. Green 'Now' = cheaper than your max in the last scan."] = "Прокрутка колесом мыши. Пропущенные предметы этот персонаж не покупает ни в этом списке, ни в следующих, пока вы не снимете отметку. Зелёное «Сейчас» = дешевле вашего максимума в последнем сканировании.",
