    ["Upgrades over what you're wearing, scored with your class's stat weights. Only gear you can use at your level, at most a quarter of your gold. Random-suffix items are scored by their base stats. Buy works at the auction house, one key press per purchase."] = "착용 장비 대비 업그레이드로, 직업별 능력치 가중치로 평가합니다. 현재 레벨에서 쓸 수 있는 장비만, 골드의 4분의 1 이하입니다. 무작위 접미사 아이템은 기본 능력치로 평가합니다. 구매는 경매장에서 구매당 키 한 번입니다.",
    ["Scroll with the mouse wheel. Skipped items are never bought on this character, on this list or later ones, until you untick them. Green 'Now' = cheaper than your max in the last scan."] = "마우스 휠로 스크롤하세요. 건너뛴 아이템은 체크를 해제할 때까지 이 캐릭터가 이 목록과 이후 목록에서 사지 않습니다. 초록색 '현재' = 마지막 스캔에서 최대치보다 저렴함.",
    ["Press the key you want for\n|cffffd200"] = "원하는 키를 누르세요:\n|cffffd200",
    ["Auto-target: nearest enemy when you have none. Tank: click an ally, then the key hits what's on them."] = "자동 대상: 대상이 없으면 가장 가까운 적. 탱커: 아군을 클릭하면 키가 그 아군을 공격하는 적을 칩니다.",
    ["Buy / post / scan buttons appear next to the auction house when you open it."] = "경매장을 열면 구매/등록/스캔 버튼이 옆에 나타납니다.",
