    ["Profit after the 5% AH cut and deposit. Only results that sell at least 3 a day; amounts sized to sell within about two days."] = "5% 경매 수수료와 보증금을 뺀 수익. 하루 3개 이상 팔리는 결과물만, 약 이틀 안에 팔릴 수량.",
