    ["Upgrades over what you're wearing, scored with your class's stat weights. Only gear you can use at your level, at most a quarter of your gold. Random-suffix items are scored by their base stats. Buy works at the auction house, one key press per purchase."] = "相对你当前装备的提升，按你职业的属性权重评分。只含你当前等级可用、价格不超过你金币四分之一的装备。随机属性物品按基础属性评分。在拍卖行购买，每次购买按一次键。",
    ["Scroll with the mouse wheel. Skipped items are never bought on this character, on this list or later ones, until you untick them. Green 'Now' = cheaper than your max in the last scan."] = "用鼠标滚轮滚动。跳过的物品在你取消勾选前，此角色在本清单和之后的清单中都不会购买。绿色“当前” = 上次扫描中低于你的上限。",
